package com.bank.recon.service;

import java.util.logging.Logger;

// Finds the single unmatched reconciliation code via XOR.
public class ReconService {
    private static final Logger log = Logger.getLogger(ReconService.class.getName());

    public int findOrphan(int[] codes) {
        int result = 0;
        for (int code : codes) result ^= code; // pairs cancel to zero
        final int orphan = result;
        log.info(() -> "Unmatched reconciliation code = " + orphan);
        return result;
    }
}
